        public void DeepCopyIn(
            INpc item,
            INpcGetter rhs,
            ErrorMaskBuilder? errorMask,
            TranslationCrystal? copyMask,
            bool deepCopy)
        {
            try
            {
                DeepCopyInInternal(
                    item: item,
                    rhs: rhs,
                    errorMask: errorMask,
                    copyMask: copyMask,
                    deepCopy: deepCopy);
            }
            catch (Exception ex)
            {
                throw RecordException.Enrich(ex, rhs);
            }
        }
        
        private void DeepCopyInInternal(
            INpc item,
            INpcGetter rhs,
            ErrorMaskBuilder? errorMask,
            TranslationCrystal? copyMask,
            bool deepCopy)
        {
            base.DeepCopyIn(
                (IFallout3MajorRecord)item,
                (IFallout3MajorRecordGetter)rhs,
                errorMask,
                copyMask,
                deepCopy: deepCopy);
            if ((copyMask?.GetShouldTranslate((int)Npc_FieldIndex.ObjectBounds) ?? true))
            {
                errorMask?.PushIndex((int)Npc_FieldIndex.ObjectBounds);
                try
                {
                    if ((copyMask?.GetShouldTranslate((int)Npc_FieldIndex.ObjectBounds) ?? true))
                    {
                        item.ObjectBounds = rhs.ObjectBounds.DeepCopy(
                            copyMask: copyMask?.GetSubCrystal((int)Npc_FieldIndex.ObjectBounds),
                            errorMask: errorMask);
