        protected NpcBinaryOverlay(
            MemoryPair memoryPair,
            BinaryOverlayFactoryPackage package)
            : base(
                memoryPair: memoryPair,
                package: package)
        {
            this.CustomCtor();
        }

        public static INpcGetter NpcFactory(
            OverlayStream stream,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            stream = Decompression.DecompressStream(stream);
            stream = ExtractRecordMemory(
                stream: stream,
                meta: package.MetaData.Constants,
                memoryPair: out var memoryPair,
                offset: out var offset,
                finalPos: out var finalPos);
            var ret = new NpcBinaryOverlay(
                memoryPair: memoryPair,
                package: package);
            ret._package.FormVersion = ret;
            ret.CustomFactoryEnd(
                stream: stream,
                finalPos: finalPos,
                offset: offset);
            ret.FillSubrecordTypes(
                majorReference: ret,
                stream: stream,
                finalPos: finalPos,
                offset: offset,
                translationParams: translationParams,
                fill: ret.FillRecordType);
            return ret;
        }

        public static INpcGetter NpcFactory(
            ReadOnlyMemorySlice<byte> slice,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            return NpcFactory(
                stream: new OverlayStream(slice, package),
                package: package,
                translationParams: translationParams);
        }

        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.OBND:
                {
                    _ObjectBoundsLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)Npc_FieldIndex.ObjectBounds;
                }
                case RecordTypeInts.FULL:
                {
                    _NameLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.Name;
                }
                case RecordTypeInts.MODL:
                case RecordTypeInts.MODB:
                case RecordTypeInts.MODT:
                case RecordTypeInts.MODS:
                case RecordTypeInts.MODD:
                {
                    this.Model = ModelBinaryOverlay.ModelFactory(
                        stream: stream,
                        package: _package,
                        translationParams: translationParams.DoNotShortCircuit());
                    return (int)Npc_FieldIndex.Model;
                }
                case RecordTypeInts.ACBS:
                {
                    _ConfigurationLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)Npc_FieldIndex.Configuration;
                }
                case RecordTypeInts.SNAM:
                {
                    this.Factions = BinaryOverlayList.FactoryByArray<IRankPlacementGetter>(
                        mem: stream.RemainingMemory,
                        package: _package,
                        translationParams: translationParams,
                        getter: (s, p, recConv) => RankPlacementBinaryOverlay.RankPlacementFactory(new OverlayStream(s, p), p, recConv),
                        locs: ParseRecordLocations(
                            stream: stream,
                            trigger: RankPlacement_Registration.TriggerSpecs,
                            triggersAlwaysAreNewRecords: true,
                            constants: _package.MetaData.Constants.SubConstants,
                            skipHeader: false));
                    return (int)Npc_FieldIndex.Factions;
                }
                case RecordTypeInts.INAM:
                {
                    _DeathItemLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.DeathItem;
                }
                case RecordTypeInts.VTCK:
                {
                    _VoiceLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.Voice;
                }
                case RecordTypeInts.TPLT:
                {
                    _TemplateLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.Template;
                }
                case RecordTypeInts.RNAM:
                {
                    _RaceLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.Race;
                }
                case RecordTypeInts.SPLO:
                {
                    this.ActorEffects = BinaryOverlayList.FactoryByArray<IFormLinkGetter<ISpellGetter>>(
                        mem: stream.RemainingMemory,
                        package: _package,
                        getter: (s, p) => FormLinkBinaryTranslation.Instance.OverlayFactory<ISpellGetter>(p, s),
                        locs: ParseRecordLocations(
                            stream: stream,
                            constants: _package.MetaData.Constants.SubConstants,
                            trigger: RecordTypes.SPLO,
                            skipHeader: true,
                            translationParams: translationParams));
                    return (int)Npc_FieldIndex.ActorEffects;
                }
                case RecordTypeInts.EITM:
                {
                    _UnarmedAttackEffectLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.UnarmedAttackEffect;
                }
                case RecordTypeInts.EAMT:
                {
                    _UnarmedAttackAnimationLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.UnarmedAttackAnimation;
                }
                case RecordTypeInts.DEST:
                case RecordTypeInts.DSTD:
                {
                    this.Destructible = DestructibleBinaryOverlay.DestructibleFactory(
                        stream: stream,
                        package: _package,
                        translationParams: translationParams.DoNotShortCircuit());
                    return (int)Npc_FieldIndex.Destructible;
                }
                case RecordTypeInts.SCRI:
                {
                    _ScriptLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.Script;
                }
                case RecordTypeInts.CNTO:
                {
                    this.Items = this.ParseRepeatedTypelessSubrecord<IContainerEntryGetter>(
                        stream: stream,
                        translationParams: translationParams,
                        trigger: ContainerEntry_Registration.TriggerSpecs,
                        factory: ContainerEntryBinaryOverlay.ContainerEntryFactory);
                    return (int)Npc_FieldIndex.Items;
                }
                case RecordTypeInts.AIDT:
                {
                    _AIDataLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)Npc_FieldIndex.AIData;
                }
                case RecordTypeInts.PKID:
                {
                    this.Packages = BinaryOverlayList.FactoryByArray<IFormLinkGetter<IPackageGetter>>(
                        mem: stream.RemainingMemory,
                        package: _package,
                        getter: (s, p) => FormLinkBinaryTranslation.Instance.OverlayFactory<IPackageGetter>(p, s),
                        locs: ParseRecordLocations(
                            stream: stream,
                            constants: _package.MetaData.Constants.SubConstants,
                            trigger: RecordTypes.PKID,
                            skipHeader: true,
                            translationParams: translationParams));
                    return (int)Npc_FieldIndex.Packages;
                }
                case RecordTypeInts.KFFZ:
                {
                    this.Animations = BinaryOverlayList.FactoryByLazyParseWithTrigger<String>(
                        stream: stream,
                        package: _package,
                        finalPos: finalPos,
                        getter: (s, p) => BinaryStringUtility.ParseUnknownLengthString(s, encoding: p.MetaData.Encodings.NonTranslated),
                        trimNullSuffix: true);
                    return (int)Npc_FieldIndex.Animations;
                }
                case RecordTypeInts.CNAM:
                {
                    _ClassLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.Class;
                }
                case RecordTypeInts.DATA:
                {
                    _DATALocation = new((stream.Position - offset) + _package.MetaData.Constants.SubConstants.TypeAndLengthLength, finalPos - offset - 1);
                    var subLen = _package.MetaData.Constants.SubrecordHeader(_recordData.Slice((stream.Position - offset))).ContentLength;
                    if (subLen <= 0xB)
                    {
                        this.DATADataTypeState |= Npc.DATADataType.Break0;
                    }
                    return (int)Npc_FieldIndex.Unused4;
                }
                case RecordTypeInts.DNAM:
                {
                    _PlayerSkillsLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)Npc_FieldIndex.PlayerSkills;
                }
                case RecordTypeInts.PNAM:
                {
                    this.HeadParts = BinaryOverlayList.FactoryByArray<IFormLinkGetter<IHeadPartGetter>>(
                        mem: stream.RemainingMemory,
                        package: _package,
                        getter: (s, p) => FormLinkBinaryTranslation.Instance.OverlayFactory<IHeadPartGetter>(p, s),
                        locs: ParseRecordLocations(
                            stream: stream,
                            constants: _package.MetaData.Constants.SubConstants,
                            trigger: RecordTypes.PNAM,
                            skipHeader: true,
                            translationParams: translationParams));
                    return (int)Npc_FieldIndex.HeadParts;
                }
                case RecordTypeInts.HNAM:
                {
                    _HairLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.Hair;
                }
                case RecordTypeInts.LNAM:
                {
                    _HairLengthLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.HairLength;
                }
                case RecordTypeInts.ENAM:
                {
                    _EyesLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.Eyes;
                }
                case RecordTypeInts.HCLR:
                {
                    _HairColorLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.HairColor;
                }
                case RecordTypeInts.ZNAM:
                {
                    _CombatStyleLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.CombatStyle;
                }
                case RecordTypeInts.NAM4:
                {
                    _ImpactMaterialTypeLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.ImpactMaterialType;
                }
                case RecordTypeInts.FGGS:
                {
                    _FaceGenGeometrySymmetricLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.FaceGenGeometrySymmetric;
                }
                case RecordTypeInts.FGGA:
                {
                    _FaceGenGeometryAsymmetricLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.FaceGenGeometryAsymmetric;
                }
                case RecordTypeInts.FGTS:
                {
                    _FaceGenTextureSymmetricLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.FaceGenTextureSymmetric;
                }
                case RecordTypeInts.NAM5:
                {
                    _NAM5Location = (stream.Position - offset);
                    return (int)Npc_FieldIndex.NAM5;
                }
                case RecordTypeInts.NAM6:
                {
                    _HeightLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.Height;
                }
                case RecordTypeInts.NAM7:
                {
                    _WeightLocation = (stream.Position - offset);
                    return (int)Npc_FieldIndex.Weight;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
        }
